where shop_code = #{shopCode}

  and categorycode = #{categoryCode}


  and categoryname like concat('%', #{categoryName}, '%')


  and `type` = #{type}


  and biztype = #{bizType}


  and isactive = #{isActive}

order by `type` desc, categorycode

